	// error, so Wait is structurally always nil; check it anyway to satisfy
	// errcheck and stay correct if that invariant ever changes.
	if err := g.Wait(); err != nil {
		fmt.Fprintf(errW, "mirror creation: %v\n", err)
	}
	prog.stop()
	return results
